Fixes: e27cca96cd68 ("xfrm: add espintcp (RFC 8229)")
Signed-off-by: Sabrina Dubroca <sd@queasysnail.net>
Reviewed-by: Simon Horman <horms@kernel.org>
Signed-off-by: Steffen Klassert <steffen.klassert@secunet.com>

Here is the root cause:
In the asynchronous crypto completion callback `esp_output_done`, the return value of `esp_output_tail_tcp` is not checked. When this function fails (e.g., due to a full TCP TX queue), it does not free the skb. With synchronous crypto, the caller handles the error, but with async crypto, the callback is responsible. The missing error handling leads to an skb leak.

Here is the patch:

 static void esp_output_done(void *data, int err)
 {
 	struct sk_buff *skb = data;
 	struct xfrm_offload *xo = xfrm_offload(skb);
 	void *tmp;
 	struct xfrm_state *x;

 	if (xo && (xo->flags & XFRM_DEV_RESUME)) {
 		struct sec_path *sp = skb_sec_path(skb);

 		x = sp->xvec[sp->len - 1];
 	} else {
 		x = skb_dst(skb)->xfrm;
 	}

 	tmp = ESP_SKB_CB(skb)->tmp;
 	esp_ssg_unref(x, tmp, skb);
 	kfree(tmp);

 	if (xo && (xo->flags & XFRM_DEV_RESUME)) {
 		if (err) {
 			XFRM_INC_STATS(xs_net(x), LINUX_MIB_XFRMOUTSTATEPROTOERROR);
 			kfree_skb(skb);
 			return;
 		}

 		skb_push(skb, skb->data - skb_mac_header(skb));
 		secpath_reset(skb);
 		xfrm_dev_resume(skb);
 	} else {
 		if (!err &&
-		    x->encap && x->encap->encap_type == TCP_ENCAP_ESPINTCP)
-			esp_output_tail_tcp(x, skb);
-		else
+		    x->encap && x->encap->encap_type == TCP_ENCAP_ESPINTCP) {
+			err = esp_output_tail_tcp(x, skb);
+			if (err != -EINPROGRESS)
+				kfree_skb(skb);
+		} else {
 			xfrm_output_resume(skb_to_full_sk(skb), skb, err);
+		}
 	}
 }



